(* [comment removed for export] *)
Ltac fold_b8 :=
  repeat match goal with |- context [bv_unsigned (Z_to_bv 8 ?z)] =>
    let v := eval vm_compute in (bv_unsigned (Z_to_bv 8 z)) in change (bv_unsigned (Z_to_bv 8 z)) with v end.
Ltac has_var c := match c with context [?x] => is_var x end.
Ltac if_closed :=
  lazymatch goal with |- evt _ _ (MS _ _ (if ?c then _ else _) _ _ _ _) =>
    tryif has_var c then fail else
    (let v := eval vm_compute in c in first [constr_eq v true | constr_eq v false]; change c with v; cbv iota) end.
Ltac fold_zext := repeat match goal with |- evt _ _ (MS ?r _ _ _ _ _ _) => match r with context [zext 64 ?e] =>
  tryif has_var e then fail else (let v := eval vm_compute in (bv_unsigned (zext 64 e)) in
    replace (zext 64 e) with (Z_to_bv 64 v) by (apply bv_eq; vm_compute; reflexivity)) end end.
Ltac fold_sx32 := repeat match goal with |- evt _ _ (MS ?r _ _ _ _ _ _) => match r with context [sx32 ?e] =>
  tryif has_var e then fail else (let v := eval vm_compute in (bv_unsigned (sx32 e)) in
    replace (sx32 e) with (Z_to_bv 64 v) by (apply bv_eq; vm_compute; reflexivity)) end end.
Ltac fold_zlit := repeat match goal with |- evt _ _ (MS ?r _ _ _ _ _ _) => match r with context [Z_to_bv 64 ?e] =>
  tryif first [is_Zlit e | has_var e] then fail else (let v := eval vm_compute in e in change (Z_to_bv 64 e) with (Z_to_bv 64 v)) end end.
Ltac fold_b2z := repeat match goal with |- evt _ _ (MS ?r _ _ _ _ _ _) => match r with context [Z.b2z ?c] =>
  tryif has_var c then fail else (let v := eval vm_compute in (Z.b2z c) in change (Z.b2z c) with v) end end.
(* [comment removed for export] *)
Ltac zdiff_lit := repeat match goal with |- evt _ _ (MS ?r _ _ _ _ _ _) => match r with context [Z_to_bv 64 (?a - ?b)] =>
  tryif has_var b then
  first [ replace (a - b) with 0 by lia | replace (a - b) with 1 by lia | replace (a - b) with (-1) by lia
        | replace (a - b) with 2 by lia | replace (a - b) with (-2) by lia | replace (a - b) with 3 by lia | replace (a - b) with (-3) by lia
        | replace (a - b) with 4 by lia | replace (a - b) with (-4) by lia ]
  else fail end end.
Ltac istep := xstep; fold_b8; fold_zext; fold_sx32; fold_b2z; fold_closed_in_goal; try (first [if_closed | if_true | if_false]).
Ltac isteps_to p := repeat (tryif at_pc p then fail else istep).
Ltac showpc := match goal with |- evt _ _ (MS _ _ ?pc _ _ _ _) => idtac "PC:" pc end.
Ltac showx n := match goal with |- evt _ _ (MS ?r _ ?pc _ _ _ _) =>
  let v := eval cbv [tget Pos.of_nat Pos.succ Pos.of_succ_nat] in (tget (Pos.of_nat (S n)) r) in idtac "PC:" pc "x" n "=" v end.
Ltac showregs := match goal with |- evt _ _ (MS ?r _ ?pc _ _ _ _) => idtac "PC:" pc "REGS:" r end.

