Ltac sf_fold SF1 := lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mm _) => lazymatch goal with H : rw_cells asegs mm ?fa
   [C4 _; C4 _; C8 (Z_to_bv 64 ?rp); C8 (Z_to_bv 64 ?re); C8 _; C8 (Z_to_bv 64 ?we); C8 (Z_to_bv 64 ?wp); C8 _; C8 (Z_to_bv 64 ?wb);
    C8 (Z_to_bv 64 ?rd); C8 _; C8 _; C8 (Z_to_bv 64 ?bu); C8 (Z_to_bv 64 ?bs); C8 _; C8 _; C4 _; C4 _; C8 _; C4 ?mo; C4 ?lk; C4 _; C4 _;
    C8 (Z_to_bv 64 ?ck); C8 _; C8 _; C8 _; C8 (Z_to_bv 64 ?se); C8 ?sl; C8 ?sc; C8 _; C8 _; C8 _] |- _ =>
  assert (SF1 : rw_cells asegs mm fa (sfile (mkSF rp re we wp wb rd bu bs mo lk ck se sl sc)))
    by (unfold sfile, w64, z32; cbn [sf_rpos sf_rend sf_wend sf_wpos sf_wbase sf_read sf_buf sf_bsz sf_mode sf_lock sf_cookie sf_shend sf_shlim sf_shcnt]; exact H)
  end end.
