Ltac sf_unfold := lazymatch goal with H : rw_cells asegs _ _ (sfile _) |- _ =>
    unfold sfile, w64, z32, string_read_entry in H;
    cbn [sf_rpos sf_rend sf_wend sf_wpos sf_wbase sf_read sf_buf sf_bsz sf_mode sf_lock sf_cookie sf_shend sf_shlim sf_shcnt length Z.of_nat Pos.of_succ_nat Pos.succ] in H;
    cbv [Z.min Z.of_nat Pos.of_succ_nat Pos.succ Z.compare Pos.compare Pos.compare_cont] in H; cbv iota beta in H;
    rename H into SF
  | |- _ => idtac "no sfile fact" end.
